{"title": "山中访友",
  "scene": "清晨，薄雾笼罩着连绵起伏的群山。小径曲折，林间不时传来鸟鸣声。白发苍苍的老人正坐在石凳上等待，身边放着一副古琴。",
  "goal": "找到山中隐士，学习一门绝技。",
  "clue": "老人身边的古琴是关键线索。",
  "choices": [
    {"id": "A", "text": "上前与老人搭话", "outcome": "老人微笑着点了点头，邀请你坐下品茶，似乎对你有所了解。他提到山中的鸟鸣是隐士到来的信号。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "直接向老人询问隐士的所在", "outcome": "老人似乎有些不悦，要求你先证明一下自己的诚意。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "寻找林间鸟鸣，尝试发现隐士", "outcome": "找到了几只鸣叫的鸟儿，但周围没有找到隐士的踪影。", "result": "success", "next": "next_level"}
  ]
}
